import type {
  BigNumberBrandVolume,
  BigNumberData,
  BigNumberDemographic,
} from 'components/BigNumber/types';

import type {
  InteractiveAudienceType,
  InteractivePercentage,
  InteractiveSelection,
} from '../../../types';
import {
  BRAND_VOLUME_EMPTY_STATE_TEXT_COLOR,
  BRAND_VOLUME_LABEL,
} from '../constants';

interface InteractiveAudienceCardOptions {
  isLoading?: boolean;
  percentage?: InteractivePercentage | null;
  emptyMessage?: string;
}

export const buildInteractiveAudienceCardData = (
  audienceType: InteractiveAudienceType,
  selection: InteractiveSelection,
  {
    isLoading = false,
    percentage = null,
    emptyMessage,
  }: InteractiveAudienceCardOptions,
): BigNumberData[] => {
  const audience: BigNumberDemographic = {
    gender: selection.gender,
    age: selection.age,
    incomeBracket: selection.income,
  };

  let brandVolume: BigNumberBrandVolume | undefined;
  if (isLoading) {
    brandVolume = {
      value: '',
      color: BRAND_VOLUME_EMPTY_STATE_TEXT_COLOR,
      label: '',
      loading: true,
    };
  } else if (percentage) {
    brandVolume = {
      value: percentage.value,
      color: percentage.color,
      label: BRAND_VOLUME_LABEL,
      measure: '%',
    };
  } else if (emptyMessage) {
    brandVolume = {
      value: '',
      color: BRAND_VOLUME_EMPTY_STATE_TEXT_COLOR,
      label: '',
      emptyStateMessage: emptyMessage,
    };
  }

  return [{ audience, audienceType, brandVolume }];
};
